export const getExportKeyValuesUrl = (
  organization: string,
  project: string,
  view: string,
) => {
  return `/v1/${encodeURIComponent(String(organization))}/${encodeURIComponent(String(project))}/${encodeURIComponent(String(view))}/key-values/export`;
};

/**
 * The pairs of the view as a 2s.key-values.v1 document. Secret values only with IncludeSecrets and secret rights; otherwise secrets are listed without a value. A POST, so that nothing secret travels in a URL. Responses with a secret value are Cache-Control: no-store.
 */
export const exportKeyValues = async (
  organization: string,
  project: string,
  view: string,
  keyValueExportRequest?: KeyValueExportRequest,
  options?: Parameters<typeof storytellerFetch>[1],
): Promise<KeyValueDocument> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return storytellerFetch<KeyValueDocument>(
    getExportKeyValuesUrl(organization, project, view),
    {
      ...options,
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...getHeaders(options?.headers),
      },
      body: JSON.stringify(keyValueExportRequest),
    },
  );
};

