/**
 * Writes a 2s.key-values.v1 document: Merge (default) writes the listed keys, Replace also soft-deletes the other active keys (under keyPrefix, when given). Items with a secret need secret rights; a secret item without a value leaves the stored secret unchanged. dryRun reports the actions without writing.
 */
export const importKeyValues = async (
  organization: string,
  project: string,
  view: string,
  keyValueDocument: KeyValueDocument,
  params?: ImportKeyValuesParams,
  options?: Parameters<typeof storytellerFetch>[1],
): Promise<KeyValueImportResult> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(
          h as Iterable<Iterable<string>>,
          (entry) => Array.from(entry) as [string, string],
        ),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<
      string | readonly string[] | undefined
    >(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
  return storytellerFetch<KeyValueImportResult>(
    getImportKeyValuesUrl(organization, project, view, params),
    {
      ...options,
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...getHeaders(options?.headers),
      },
      body: JSON.stringify(keyValueDocument),
    },
  );
};

